// HasSourceShipment applies the HasEdge predicate on the "source_shipment" edge.
func HasSourceShipment() predicate.ReworkIntake {
	return predicate.ReworkIntake(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, false, SourceShipmentTable, SourceShipmentColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasSourceShipmentWith applies the HasEdge predicate on the "source_shipment" edge with a given conditions (other predicates).
